// Pane widths are viewport preferences, not document state. The active pane is clamped against
// both its own limits and the opposite pane so a drag always leaves a useful canvas viewport.
function clampPaneWidth(requested, oppositeWidth, availableWidth) {
  const wanted = Number.isFinite(Number(requested)) ? Number(requested) : PANE_MIN_WIDTH;
  const opposite = Math.max(PANE_MIN_WIDTH, Math.min(PANE_MAX_WIDTH, Number(oppositeWidth) || PANE_MIN_WIDTH));
  const room = Number.isFinite(Number(availableWidth))
    ? Number(availableWidth) - opposite - CANVAS_MIN_WIDTH
    : PANE_MAX_WIDTH;
  const upper = Math.max(PANE_MIN_WIDTH, Math.min(PANE_MAX_WIDTH, room));
  return Math.max(PANE_MIN_WIDTH, Math.min(upper, wanted));
}

// Reconcile both panes when the browser itself narrows. Under 600px the three minima cannot all
// fit, so the panes keep their 180px floors; at every feasible width the canvas keeps 240px.
function clampPaneWidths(leftWidth, rightWidth, availableWidth) {
  let left = Math.max(PANE_MIN_WIDTH, Math.min(PANE_MAX_WIDTH, Number(leftWidth) || LEFT_PANE_DEFAULT));
  let right = Math.max(PANE_MIN_WIDTH, Math.min(PANE_MAX_WIDTH, Number(rightWidth) || RIGHT_PANE_DEFAULT));
  if (!Number.isFinite(Number(availableWidth))) return { left, right };
  let excess = left + right - Math.max(PANE_MIN_WIDTH * 2, Number(availableWidth) - CANVAS_MIN_WIDTH);
  if (excess <= 0) return { left, right };
  const rightReduction = Math.min(excess, right - PANE_MIN_WIDTH);
  right -= rightReduction;
  excess -= rightReduction;
  left -= Math.min(excess, left - PANE_MIN_WIDTH);
  return { left, right };
}

